<script setup>
import { computed, ref } from 'vue';
const props=defineProps({items:{type:Array,default:()=>[]},completado:{type:Boolean,default:false}});const emit=defineEmits(['reproducir','hablar','practicar']);
const paso=ref(1),sujetoId=ref('i'),accionId=ref('write'),contexto=ref('right now'),verboLab=ref('write'),retoIdx=ref(0),elegida=ref(null),aciertos=ref(new Set());
const sujetos=[{id:'i',texto:'I',be:'am',icono:'🙋'},{id:'she',texto:'She',be:'is',icono:'👩'},{id:'he',texto:'He',be:'is',icono:'👨'},{id:'we',texto:'We',be:'are',icono:'👥'},{id:'they',texto:'They',be:'are',icono:'🧑‍🤝‍🧑'},{id:'team',texto:'The team',be:'is',icono:'🛠️'}];
const acciones=[{id:'write',base:'write',ing:'writing',objeto:'the report',icono:'✍️',regla:'quita e + ing'},{id:'fix',base:'fix',ing:'fixing',objeto:'a bug',icono:'🐛',regla:'+ ing'},{id:'run',base:'run',ing:'running',objeto:'a test',icono:'🧪',regla:'duplica consonante'},{id:'study',base:'study',ing:'studying',objeto:'English',icono:'📚',regla:'+ ing'},{id:'lie',base:'lie',ing:'lying',objeto:'on the sofa',icono:'🛋️',regla:'ie → y + ing'},{id:'migrate',base:'migrate',ing:'migrating',objeto:'the database',icono:'🗄️',regla:'quita e + ing'}];
const sujeto=computed(()=>sujetos.find(x=>x.id===sujetoId.value)),accion=computed(()=>acciones.find(x=>x.id===accionId.value)),demo=computed(()=>acciones.find(x=>x.id===verboLab.value));const frase=computed(()=>`${sujeto.value.texto} ${sujeto.value.be} ${accion.value.ing} ${accion.value.objeto} ${contexto}.`);
const retos=[{icono:'🛠️',frase:'Right now, the team ___ a critical bug.',respuesta:'is fixing',opciones:['fixes','is fixing','are fixing','fixing'],ayuda:'The team es singular: is + fixing.'},{icono:'✍️',frase:'I ___ the postmortem at the moment.',respuesta:'am writing',opciones:['write','am writing','is writing','writing'],ayuda:'Con I usamos am + verbo-ing.'},{icono:'🗄️',frase:'They ___ the database this week.',respuesta:'are migrating',opciones:['migrate','is migrating','are migrating','migrating'],ayuda:'They usa are; migrate pierde la e.'},{icono:'❓',frase:'___ you working on the feature today?',respuesta:'Are',opciones:['Do','Are','Is','Does'],ayuda:'En preguntas, am/is/are pasa al frente.'}];const reto=computed(()=>retos[retoIdx.value]),correcta=computed(()=>elegida.value===reto.value.respuesta);
function escuchar(t){emit('hablar',t,1)}function responder(o){elegida.value=o;if(o===reto.value.respuesta){const s=new Set(aciertos.value);s.add(retoIdx.value);aciertos.value=s}}function siguiente(){retoIdx.value=(retoIdx.value+1)%retos.length;elegida.value=null}
</script>
<template><section class="pc"><aside class="hero"><div><small>📡 EN VIVO</small><h2>Presente continuo = en progreso</h2><p><b>am / is / are + verbo-ing</b> para lo que ocurre ahora o durante un periodo temporal.</p></div><div class="formula"><span>SUJETO</span><i>＋</i><span>AM · IS · ARE</span><i>＋</i><span>VERBO-ING</span></div></aside><nav><button v-for="n in 3" :key="n" :class="{active:paso===n}" @click="paso=n"><b>0{{n}}</b><span>{{n===1?'Estudio en vivo':n===2?'Taller -ing':'Radar del ahora'}}</span></button></nav>
<main v-if="paso===1"><header><small>PRESENTE CONTINUO 1</small><h3>¿Qué está pasando?</h3><p>Armá una escena en tiempo real y escuchá el resultado.</p></header><div class="picker"><section><b>1. Quién</b><button v-for="x in sujetos" :key="x.id" :class="{active:sujetoId===x.id}" @click="sujetoId=x.id"><span>{{x.icono}}</span>{{x.texto}}</button></section><section><b>2. Acción</b><button v-for="x in acciones" :key="x.id" :class="{active:accionId===x.id}" @click="accionId=x.id"><span>{{x.icono}}</span>{{x.base}}</button></section><select v-model="contexto"><option>right now</option><option>at the moment</option><option>today</option><option>this week</option></select></div><article class="live"><i></i><span>{{sujeto.icono}} {{accion.icono}}</span><small>LIVE NOW</small><strong>{{frase}}</strong><button @click="escuchar(frase)">🔊 Escuchar escena</button></article></main>
<main v-else-if="paso===2"><header><small>PRESENTE CONTINUO 2</small><h3>Laboratorio de terminaciones</h3><p>Elegí un verbo y observá cómo se transforma.</p></header><div class="lab"><div><button v-for="x in acciones" :key="x.id" :class="{active:verboLab===x.id}" @click="verboLab=x.id"><span>{{x.icono}}</span><b>{{x.base}}</b></button></div><article><small>BASE</small><b>{{demo.base}}</b><i>{{demo.regla}}</i><em>→</em><small>FORMA -ING</small><strong>{{demo.ing}}</strong><button @click="escuchar(`I am ${demo.ing}.`)">🔊 I am {{demo.ing}}.</button></article></div><section class="rules"><p><b>Normal</b>fix → fixing</p><p><b>-e final</b>write → writing</p><p><b>CVC</b>run → running</p><p><b>-ie final</b>lie → lying</p></section></main>
<main v-else><header class="challenge-head"><div><small>PRESENTE CONTINUO 3</small><h3>Radar del ahora</h3><p>Detectá la forma que mantiene la acción en movimiento.</p></div><b>{{aciertos.size}}/{{retos.length}}</b></header><article class="challenge"><span>{{reto.icono}}</span><button @click="escuchar(reto.frase.replace('___',reto.respuesta))">{{reto.frase}} 🔊</button><div><button v-for="o in reto.opciones" :key="o" :class="{ok:elegida&&o===reto.respuesta,bad:elegida===o&&o!==reto.respuesta}" @click="responder(o)">{{o}}</button></div><p v-if="elegida"><b>{{correcta?'✓ ¡En vivo!':'↻ Casi'}}</b> {{reto.ayuda}}</p><button v-if="correcta" class="next" @click="siguiente">Siguiente señal →</button></article></main><button class="practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>
